From a1dbfac3e285824a08878db91fec5b951165d060 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:06:28 +0100
Subject: [PATCH] applet: add an action to play and record all audio via one
 device

Switching a headset or other device that can both play and record took
two separate actions, one for its output and one for its input. Devices
on a card with both now offer one menu action that switches both at once.

BUG: 432120
---
 src/qml/listitemmenu.cpp | 33 +++++++++++++++++++++++++++++++++
 1 file changed, 33 insertions(+)

diff --git a/src/qml/listitemmenu.cpp b/src/qml/listitemmenu.cpp
index 631e2cd7..811cbe0d 100644
--- a/src/qml/listitemmenu.cpp
+++ b/src/qml/listitemmenu.cpp
@@ -17,10 +17,13 @@
 #include <KLocalizedString>

 #include <PulseAudioQt/Card>
+#include <PulseAudioQt/Context>
 #include <PulseAudioQt/Device>
 #include <PulseAudioQt/Models>
 #include <PulseAudioQt/Port>
 #include <PulseAudioQt/PulseObject>
+#include <PulseAudioQt/Sink>
+#include <PulseAudioQt/Source>
 #include <PulseAudioQt/Stream>

 #include "debug.h"
@@ -333,6 +336,36 @@ QMenu *ListItemMenu::createMenu()
             if (switchStreamsAction) {
                 connect(switchStreamsAction, &QAction::triggered, device, &Device::switchStreams);
             }
+
+            // Switch both directions at once to a physical device that can play and record, like a headset
+            Device *counterpart = nullptr;
+            if (device->cardIndex() != static_cast<quint32>(-1)) {
+                QList<Device *> candidates;
+                if (m_itemType == Sink) {
+                    const auto sources = Context::instance()->sources();
+                    candidates = {sources.cbegin(), sources.cend()};
+                } else if (m_itemType == Source) {
+                    const auto sinks = Context::instance()->sinks();
+                    candidates = {sinks.cbegin(), sinks.cend()};
+                }
+                for (Device *candidate : std::as_const(candidates)) {
+                    if (candidate->cardIndex() == device->cardIndex() && (!counterpart || candidate->isDefault())) {
+                        counterpart = candidate;
+                    }
+                }
+            }
+
+            if (counterpart) {
+                auto *switchAllAction = menu->addAction(QIcon::fromTheme(QStringLiteral("audio-headset")), i18n("Play and record all audio via this device"));
+                connect(switchAllAction, &QAction::triggered, device, [device, counterpart = QPointer<Device>(counterpart)] {
+                    device->setDefault(true);
+                    device->switchStreams();
+                    if (counterpart) {
+                        counterpart->setDefault(true);
+                        counterpart->switchStreams();
+                    }
+                });
+            }
         }

         // Ports
